function renderOperationMetadataFields(type){
const fields=operationMetadataFields(type);
if(!fields.length)return '';
return '<section class="operation-metadata-panel"><div class="section-kicker">INDUSTRY DETAILS</div><div class="form-grid">'+fields.map(([key,label,type,required])=>{let input;if(type.startsWith('select:'))input='<select name="meta_'+key+'" '+(required?'required':'')+'>'+type.slice(7).split(',').map(v=>'<option value="'+esc(v)+'">'+esc(nice(v))+'</option>').join('')+'</select>';else input='<input name="meta_'+key+'" type="'+esc(type)+'" '+(required?'required':'')+(type==='number'?' min="0" step="0.01"':'')+'>';return '<label class="'+(type==='textarea'?'wide':'')+'">'+esc(label)+input+'</label>';}).join('')+'</div></section>';
}
